    [0, 0, 0, 3, 0, 0, 0, 3, 0, 0, 0],
    [0, 0, 0, 3, 0, 0, 0, 3, 0, 5, 5],
]

# Proper 3x3 regions (each region has cols 0-2, 4-6, 8-10 not 3-5)
# Region 0: cols 0-2
# Region 1: cols 4-6
# Region 2: cols 8-10

region_5counts = []
for r in range(3):
    row_counts = []
    for c in range(3):
        def start_col(c_idx):
            if c_idx == 0: return 0
            if c_idx == 1: return 4
            if c_idx == 2: return 8

        region_cells = []
        for rr in range(0, 11):
            for cc in range(0, 11):
                # Skip separators (row 3,7 and col 3,7)
                if rr in [3, 7]: continue
                if cc in [3, 7]: continue

                if rr >= r*3 and rr < r*3+3:
                    if cc >= start_col(c) and cc < start_col(c) + 3:
                        region_cells.append(test_input[rr][cc])

        row_counts.append(sum(1 for x in region_cells if x == 5))
    region_5counts.append(row_counts)

print("Correct 5 counts:")
for row in region_5counts:
    print(row)

print("\nRegion contents (top row):")
for r in range(3):
    print(f"[{r}]")
    for c in range(3):
        region = []
        def start_col(c_idx):
            if c_idx == 0: return 0
            if c_idx == 1: return 4
            if c_idx == 2: return 8

        for rr in range(0, 11):
            for cc in range(0, 11):
                if rr in [3, 7]: continue
                if cc in [3, 7]: continue
                if rr >= r*3 and rr < r*3+3:
                    if cc >= start_col(c) and cc < start_col(c) + 3:
                        region.append(test_input[rr][cc])
        print(f"  [{r}][{c}]: {region}")

print("\nRegion contents (middle row):")
for r in range(6, 9):
    print(f"[{r}]")
    for c in range(3):
        region = []
        def start_col(c_idx):
            if c_idx == 0: return 0
            if c_idx == 1: return 4
            if c_idx == 2: return 8

        for rr in range(0, 11):
            for cc in range(0, 11):
                if rr in [3, 7]: continue
                if cc in [3, 7]: continue
                if rr >= r*3 and rr < r*3+3:
                    if cc >= start_col(c) and cc < start_col(c) + 3:
                        region.append(test_input[rr][cc])
        print(f"  [{r}][{c}]: {region}")

# Submit the solution
